      "full_text" : "中推小巨蛋女流氓如果如歌\n裹挟已经发疯的“我爸是李刚”装逼犯被窝公主穷途末路\n因其杀猪盘真相被揭露\n制造网络白色恐怖\n扬言七七四十九天谩骂造谣污蔑女网友\n使用杀猪盘专业手法开设无数小号\n恶意传播其制作的淫秽裸体照片和视频\n并且对该女网友进行羞辱陷害\n人肉敲诈勒索\n叫嚣把该女网友打出中推。。 https://t.co/ypA6eiB6c1",
