      "favorited" : false,
      "full_text" : "#小巨蛋 #杨家将 #辱疙如歌 连体号用户名被网友解读成黄推 2023-10-9️快听\n小巨蛋杨家将云卖唱跨国杀猪盘⚠️\n自爆洗脑走线网友花钱开公司花钱办身份\n实际上此骗子人在中国东北农村\n见识短浅\n故意使用黄推用户名\n被窝公主\n冒充高官家属\n叫嚣“我爸是李刚”威胁走线网友\n男网友一不留神就上当 https://t.co/uIK5lsntzW",
