      "favorited" : false,
      "full_text" : "23-10-3 小巨蛋杨家将云卖唱假装在美国\n说自己是学经贸的\n那点金贸常识\n估计连初中都没毕业\n裸聊林汉和颖资\n骗取夹克马信任\n陷害诸多女网友\n长相丑陋却要与人比美\n网络盗图拿来与人比富\n意淫自己高官公主耍虚拟威风\n三观扭曲\n口头禅是\n我爸是李刚\n我的肉可贵了\n老鸡婆穷鬼装嫩装逼\n蹭别人炒作自己 https://t.co/CoyilhDBgs",
