      "created_at" : "Fri Sep 29 22:26:31 +0000 2023",
      "favorited" : false,
      "full_text" : "这是谁在说它的肉可贵了\n杨家将小巨蛋云卖唱如割说\n她的肉可贵了\n她是惜肉如金的\n😂实锤卖逼\n把自己身体当猪肉换金子了\n真的很贵吗\n越说自己贵就越贱\n越贱越炫\n自吹自擂\n自我吹嘘和自我夸大的心理状态\n对自己认知不足\n源于自卑感或者渴望被接受的需要\n做婊子又要立牌坊\n连凤姐都甩它48条马路 https://t.co/NsbVYkrLqq",
